/** Объект расширения по идентификатору. */
export function facilityExpansionById(id: string): FacilityExpansion | undefined {
  return FACILITIES_EXPANSION.find((facility) => facility.id === id);
}

/** Объекты расширения по стране размещения. */
export function facilitiesExpansionByHost(iso3: string): FacilityExpansion[] {
  return FACILITIES_EXPANSION.filter((facility) => facility.hostIso === iso3);
}

/** Объекты расширения по стране-оператору (включая зарубежные базы). */
export function facilitiesExpansionByOperator(iso3: string): FacilityExpansion[] {
  return FACILITIES_EXPANSION.filter((facility) => facility.operatorIso === iso3);
}

/** Объекты расширения по типу. */
export function facilitiesExpansionByType(type: FacilityExpansionType): FacilityExpansion[] {
  return FACILITIES_EXPANSION.filter((facility) => facility.type === type);
}

/** Сводка расширения: число объектов по типам. */
export function facilityExpansionTypeCounts(): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const facility of FACILITIES_EXPANSION) {
    counts[facility.type] = (counts[facility.type] ?? 0) + 1;
  }
  return counts;
}

